"""Faithful private Veinot1997 source crops, preserving original pixels and captions."""
import json,hashlib,math
from pathlib import Path
import pypdfium2 as pdfium
from PIL import Image,ImageDraw,ImageFont
ROOT=Path(__file__).resolve().parent
OUT=ROOT/'crop-assets';OUT.mkdir(exist_ok=True)
(OUT/'source-render').mkdir(exist_ok=True)
SOURCE=Path('[local path redacted]')
EXPECTED='eac4fe78e4bc3ab9c15e0409b69232e4294a0c07787d3ca650c378f6341d4adc'
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def dump(p,x):p.write_text(json.dumps(x,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
assert sha(SOURCE)==EXPECTED
assets=[]
def add(id,page,box,title,caption,scope,kind='figure',evidence='experimental',notes=None,panels=None):
 assets.append(dict(id=id,pdf_page=page,box=box,title=title,caption_paraphrase=caption,sample_scope=scope,type=kind,evidence_type=evidence,scope_caveats=notes or [],panels=panels or []))
add('compound-family-illustration',2,[99,69,578,884],'Source illustration of QDOH and five ester derivatives','Original schematic of surface-phenolic CdS, compound1, and esterified family2 with substituents a–e.','Source identities:1=QDOH;2a=acetyl,2b=butanoyl,2c=pyrene-1-carbonyl,2d=benzoyl,2e=decanoyl derivatives.',kind='compound_illustration',evidence='conceptual_chemical_structure',notes=['Circles and five depicted caps are conceptual, not measured nanocluster geometry, ligand counts or atomic coordinates.','The simplified drawing connects the aromatic cap to the CdS circle without explicitly drawing every surface S site; the text describes sulfur-bound thiolate.','No CdS polymorph is determined by this drawing. All substituent labels and the pyrene structure are preserved.'])
add('table-01',3,[99,66,1090,423],'Reaction conditions, precursor yields and ester conversion with NMR','Tabulated synthesis time/solvent, yield or conversion, and proton-NMR assignments for1,2a–e and3a–e.','1=QDOH;2a–e=cluster ester conversions;3a–e=N-acylimidazole small-molecule yields.',kind='table',evidence='reported_conditions_and_characterization',notes=['Cluster conversion percentages are phenolic esterification fractions estimated by NMR; they are not isolated mass yield or photoluminescence yield.','3b lists15min while the general anhydride method says30min.3d lists15min; the general chloride procedure lacks a hold time.','The3d benzoyl entry includes an anomalous2.6ppm methyl resonance; retain as printed, not an inferred change to toluoyl identity.','QDOH has a blank yield/conversion cell, not zero. Table time applies to its specified synthesis, not the NMR acquisition.'])
add('table-02',3,[99,432,1090,833],'FTIR bands and assignments across QDOH and esters','FTIR peak positions and qualitative intensities for the six nanocluster identities as KBr pellets.','1 and2a–e; spectral specimen rather than a separate synthesis batch.',kind='table',notes=['Original legend and all rows retained.','The text and table differ slightly for some QDOH band values (3301/3302 and1730/1734cm−1); do not silently harmonize.','C=O and C=C are chemical bond symbols, not CdO or CdC from plain-text extraction.'])
add('table-03',3,[99,843,578,1087],'Optical and TEM cluster size comparison','Optical bands, band-model calculated diameters and TEM-measured diameters for1 and2a–e.','Measured TEM diameters:1 30.4Å;2a27.3Å;2b24.7Å;2c26.3Å;2d28.2Å;2e28.2Å. Calculated optical diameters are distinct evidence.',kind='table',evidence='measurement_and_model_estimate',notes=['2c has a356–420nm pyrene transition range and no model-derived CdS diameter, because pyrene masks the CdS absorption. Blank model size is not zero.','The header refers to Eq1, but no numbered equation is printed in the supplied six-page article. No equation is reconstructed.','QDOH390nm band-to-band value conflicts with the Experimental295nm edge/305nm shoulder; preserve source scope.','No exact individual reaction batch or crystal structure is identified by the compound label alone.'])
add('scheme-01',3,[610,841,1090,1126],'N-acylimidazole preparation and surface acyl transfer','Imidazole/acyl-chloride route to3 followed by transfer of acyl group toQDOH, giving ester2 and imidazole.','General reaction family, mapping3a–e acyl identities to2a–e.',kind='scheme',evidence='reaction_scheme',notes=['The actual preparation of3a and3b uses corresponding acid anhydrides, despite the general scheme showing RCOCl.','Imidazole hydrochloride is the byproduct of the chloride-based precursor preparation, not proof that HCl is applied directly to QDOH.','The diagram supplies molecular connectivity but not kinetics, transition states or a measured surface structure.'])
add('figure-01',4,[99,65,578,634],'QDOH proton NMR before and after D2O','Two400MHz proton-NMR spectra ofQDOH inDMSO-d6; panelb follows addition of one drop ofD2O.','Compound1,QDOH, NMR exchange experiment.',panels=['a:beforeD2O','b:afteroneD2Odrop'],notes=['Panels and caption remain together.','Loss of the broad8.6–9.1ppm signal supports assignment to exchangeableOH; it is not a new synthesis sample or complete material conversion.','The different displayed spectral ranges are retained; no axis or integration trace is digitized.'])
add('figure-02',4,[610,65,1090,392],'N-decanoylimidazole precursor proton NMR','400MHz proton-NMR spectrum of3e inDMSO-d6 with residual solvent marked by an asterisk.','Small-molecule precursor3e, not decanoylated nanocluster2e.',notes=['Precursor and product spectra must not be swapped. The source’s assignment and original signal labels remain intact.'])
add('figure-03',4,[610,403,1090,730],'Decanoylated CdS nanocluster proton NMR','400MHz proton-NMR spectrum of2e inCDCl3 with residual chloroform, water andTMS markers.','Compound2e nanocluster ester; distinct from3e precursor and from theDMSO-d6 used for other cluster NMR specimens.',notes=['Asterisk marks chloroform, double dagger water, dagger TMS; glyphs are preserved.','No molecular formula, ligand count or sample mass is determined by this crop.'])
add('figure-04',5,[99,67,954,650],'Decanoylated nanocluster infrared spectrum','FTIR spectrum of2e prepared inKBr.','Compound2e; NMR,IR and TEM preparations are separate analytical specimen states.',notes=['The original axis is percent transmittance despite the caption describing infrared absorption. Retain original representation.','The spectrum is not digitized or redrawn.'])
add('figure-05',5,[610,655,1090,1039],'QDOH optical absorption in methanol','Original optical spectrum of10−4M QDOH in methanol with a1cm path.','Compound1, dilute optical specimen; concentration molar basis for nanoclusters is not further defined.',notes=['Text assigns an onset near390nm, while Experimental reports295nm edge and305nm shoulder. The original plot and both statements remain available.','3.19eV optical gap and24Å tight-binding diameter are source-derived interpretations, not TEM measurements.'])
add('figure-06',6,[610,65,1090,592],'TEM of QDOH with aggregates and individual clusters','Original TEM image of driedQDOH from aCHCl3 suspension on carbon-coated copper, caption magnification290000×.','Compound1, TEM specimen; the image includes an aggregate and neighboring particles.',evidence='experimental_tem',notes=['Original6nm scale bar is preserved. Body describes a1100Å aggregate, which appears inconsistent with the image scale; do not recalculate or replace the scale.','Caption namesQDOH inCHCl3, while the discussion saysQDOH is not soluble inCHCl3. A deposited suspension need not be molecularly dissolved; preserve both statements.','The body reports30.4±7Å from histogram analysis; superscript15 is a resolution-limitation footnote, not part of715Å. It does not identify every visible object with this diameter.','No lattice fringes, SAED, XRD or measured atomic coordinates are provided.'])
doc=pdfium.PdfDocument(SOURCE);assert len(doc)==6
renders={}
for p in range(1,7):
 im=doc[p-1].render(scale=300/72).to_pil().convert('RGB');im.save(OUT/'source-render'/f'pdfium-{p:02d}-300dpi.png');renders[p]=im
for s in assets:
 norm=[s['box'][0]/1190,s['box'][1]/1540,s['box'][2]/1190,s['box'][3]/1540]
 im=renders[s['pdf_page']];bbox=[round(norm[i]*(im.width if i%2==0 else im.height)) for i in range(4)];crop=im.crop(bbox);p=OUT/(s['id']+'.png');crop.save(p)
 w,h=doc[s['pdf_page']-1].get_size()
 s.update(source_id='veinot1997',source_doi='10.1021/cm970189m',source_file=SOURCE.name,source_path=str(SOURCE),source_sha256=EXPECTED,printed_page=2116+s['pdf_page'],relative_asset=p.name,sha256=sha(p),dpi=300,pixel_dimensions=list(crop.size),crop_normalized=norm,bbox_pixels_at_140dpi=s.pop('box'),bbox_pdf_points_top_left=[norm[i]*(w if i%2==0 else h) for i in range(4)],original_source_asset=True,synthetic=False,digitized=False,eligible_training=False,experimental_sample_cif=False,original_caption_preserved=True,visually_reviewed=False,renderer='PDFium via pypdfium2; original PDF rasterization and rectangular crop, no redrawing')
manifest={'source_id':'veinot1997','source_doi':'10.1021/cm970189m','source_title':'Surface Functionalization of Cadmium Sulfide Quantum-Confined Nanoclusters. 3. Formation and Derivatives of a Surface Phenolic Quantum Dot','source_sha256':EXPECTED,'source_file':SOURCE.name,'source_page_count':6,
 'coverage':{'all_source_pages_text_read':True,'all_source_pages_visually_reviewed':True,'numbered_figures':6,'numbered_tables':3,'schemes':1,'compound_illustrations':1,'numbered_equations':0,'crop_count':len(assets),'individual_crops_visually_reviewed':False},
 'source_pages':[{'pdf_page':p,'text_read':True,'visual_review':True,'text_sha256':sha(ROOT/f'plain-page-{p}.txt'),'initial_render_sha256':sha(ROOT/f'main-{p:02d}.png')} for p in range(1,7)],
 'assets':assets,'global_limits':['The header ofTable3 references Eq1, but no such equation is printed in the six supplied pages.','Compound labels distinguish families; no exact physical batch IDs are invented.','CdS phase, measured atomic coordinates and ligand count are not established by the source schematics.','11 original crops only; no synthetic spectra, digitized points, reconstruction or new atomic models.']}
dump(OUT/'manifest.json',manifest)
font=ImageFont.truetype('C:/Windows/Fonts/arial.ttf',22)
for i in range(math.ceil(len(assets)/4)):
 sheet=Image.new('RGB',(1800,1600),'#eeeeee');draw=ImageDraw.Draw(sheet)
 for n,s in enumerate(assets[i*4:i*4+4]):
  x=n%2*900;y=n//2*800;im=Image.open(OUT/s['relative_asset']).convert('RGB');im.thumbnail((878,752));draw.text((x+12,y+8),s['id']+' / PDF p'+str(s['pdf_page']),font=font,fill='black');sheet.paste(im,(x+11,y+40))
 sheet.save(OUT/f'contact-{i+1:02d}.png')
print(json.dumps({'assets':len(assets),'sha256':sha(OUT/'manifest.json')}))
